####################################################
# create_people_poster.ps1
# v2.7
# author: bullmoose20
#
# DESCRIPTION: 
# Generates posters from transparent PNGs in config\people_dirs\Downloads.
# It will then scan and produce 5 people poster files all at 2000x3000 in size
# bw-style
# diiivoy-style
# diiivoycolor-style
# rainier-style
# signature-style
#
# And then copies out the original and the transparent file that can be used for future poster styles
# original-style
# transparent
#
# REQUIREMENTS:
# Imagemagick must be installed - https://imagemagick.org/script/download.php
# Powershell 7.x
# Powershell security settings: https://learn.microsoft.com/en-us/powershell/module/microsoft.powershell.core/about/about_execution_policies?view=powershell-7.2
#
# NOTE:
# This version assumes backgrounds are already removed (transparent PNGs).
# Drop ready PNGs into .\config\people_dirs\Downloads\
# 
# EXAMPLE:
# .\create_people_poster.ps1
####################################################

param ()

#################################
# 8 files to be extracted for poster creation
# file1=@zbase-People.jpg
# file2=@zbase-People-Clear2.png
# file3=@zbase-Signature.png
# file4=Comfortaa-Medium.ttf
# file5=Fuggles-Regular.ttf
# file6=Montserrat-SemiBold.ttf
# file7=FuturaTEELig.ttf
# file8=@zbase-People-Clear3.png
#################################
$file1 = ""
$file2 = ""
$file3 = ""
$file4 = ""
$file5 = ""
$file6 = ""
$file7 = ""
$file8 = ""

#################################
# GLOBAL VARS
#################################
$global:Counter1 = 0
$global:Counter2 = 0
$global:Counter3 = 0
$global:Counter4 = 0
$global:Counter5 = 0
$global:Counter6 = 0
$global:Counter7 = 0
$global:magick = $null

#################################
# ImageMagick shim (cross-platform, relocatable)
#################################

Function Get-ImageMagick {
  $identify = $null; $convert = $null; $root = $null

  if (Get-Command magick -ErrorAction SilentlyContinue) {
    $root     = "magick"
    $identify = { param([Parameter(ValueFromRemainingArguments=$true)] $rest) & magick identify @rest }
    $convert  = { param([Parameter(ValueFromRemainingArguments=$true)] $rest) & magick @rest }
  } else {
    if (Get-Command identify -ErrorAction SilentlyContinue) {
      $identify = { param([Parameter(ValueFromRemainingArguments=$true)] $rest) & identify @rest }
    }
    if (Get-Command convert -ErrorAction SilentlyContinue) {
      $convert  = { param([Parameter(ValueFromRemainingArguments=$true)] $rest) & convert  @rest }
    }
  }

  if (-not $identify -or -not $convert) {
    throw "ImageMagick not found on PATH. Install it and try again."
  }

  [pscustomobject]@{
    Root     = $root
    Identify = $identify
    Convert  = $convert
  }
}

# Global IM handle
$script:IM = $null
# =========================================================

#################################
# collect paths (cross-platform, relocatable)
#################################

# Where this script lives
$script_path = if ($PSScriptRoot) { $PSScriptRoot } else { Split-Path -Path $MyInvocation.MyCommand.Path -Parent }

# Names
$scriptName = $MyInvocation.MyCommand.Name
$scriptBaseName = [IO.Path]::GetFileNameWithoutExtension($scriptName)

# ── Config roots ────────────────────────────────────────────────────────────────
$cfgRoot = Join-Path $script_path 'config'
$logsDir = Join-Path $cfgRoot 'logs'
$peopleRoot = Join-Path $cfgRoot 'people_dirs'   # <- NEW: all “other” dirs live here

# Logs (.\config\logs\create_people_poster.log)
New-Item -ItemType Directory -Path $logsDir -Force | Out-Null
$scriptLog = Join-Path $logsDir "$scriptBaseName.log"

# ── People/output working tree under .\config\people_dirs ─────────────────────
$download_dir = Join-Path $peopleRoot 'Downloads'
