$fontMontserrat = Join-Path $basePath 'Montserrat-SemiBold.ttf'
$fontFutura = Join-Path $basePath 'FuturaTEELig.ttf'

#################################
# Create dirs
#################################
$dirsToMake = @(
  $download_dir,
  $targetPath_bw, $targetPath_diiivoy, $targetPath_diiivoycolor,
  $targetPath_rainier, $targetPath_orig, $targetPath_signature,
