    }
    else {
      WriteToLogFile "Alert-check                  : FOUND JR. in name"
      $tmp1 = Get-Width ($postertitle2[1] + " " + $postertitle2[2]) $fontComfortaa 183
      $tmp2 = Get-Width ($postertitle2[0]) $fontComfortaa 183
      if ($tmp1 -ge 1600) {
