#################################
# Test-Image function
#################################
Function Test-Image {

  $imageW = & $script:IM.Identify -format "%w" $filepre
  $imageH = & $script:IM.Identify -format "%h" $filepre
  $imageRatio = [math]::Round($imageW / $imageH, 4)

  # Find if image is grayscale
  $theString = & $script:IM.Identify -verbose $filepre | Select-String -Pattern Type: -CaseSensitive
  $found = $theString | Select-String -Pattern 'Gray' -CaseSensitive -SimpleMatch
  if ($found) {
    $global:Counter1++
    WriteToLogFile "WARNING                      : WARNING1!~$filepre~$noextension is Grayscale! Find a color image for $noextension on TMDB and re-process"
  }

  # Find if background is removed and hence has transparency
  $string = & $script:IM.Convert $filepre -format "%[opaque]" info:
  $found = $string | Select-String -Pattern 'True' -CaseSensitive -SimpleMatch
  if ($found) {
    $global:Counter2++
    WriteToLogFile "WARNING                      : WARNING2!~$filepre~$noextension is NOT Transparent and needs background removed!"
  }

  # Find if first line is transparent to determine if there is a head chop situation
  $string = & $script:IM.Convert $filepre -crop x1+0+0 +repage -alpha extract -format %[fx:mean] info:
  if ($string -gt .06) {
    $global:Counter3++
    WriteToLogFile "WARNING                      : WARNING3!~$filepre~$noextension is most likely a HEAD CHOP and should be reviewed and changed for a better headshot!~Headchop values~$string"
  }
  
  if ($baseImageRatio -eq $imageRatio) {
  }
  else {
    $global:Counter4++
    WriteToLogFile "WARNING                      : WARNING4!~$filepre~$noextension Ratio should be $baseImageRatio, however this image is >$imageRatio<"
  }

  if ($imageW - $baseImageW -gt 0) {
  }
  else {
    $global:Counter5++
    WriteToLogFile "WARNING                      : WARNING5!~$filepre~$noextension Quality of source could be a problem. Image width should be > $baseImageW, however this image is >$imageW< wide"
  }

  if ($imageH - $baseImageH -gt 0) {
  }
  else {
    $global:Counter6++
    WriteToLogFile "WARNING                      : WARNING6!~$filepre~$noextension Quality of source could be a problem. Image height should be > $baseImageH, however this image is >$imageH< high"
  }

  if ($imageW -eq 2000 -and $imageH -eq 3000) {
  }
  else {
    $global:Counter7++
    WriteToLogFile "WARNING                      : WARNING7!~$filepre~$noextension File dimensions should be 2000 x 3000, however this image is >$imageW x $imageH<"
  }

}

#################################
# Push-Down function
#################################
Function Push-Down ([bool]$b) {

  if ($b) {
	# Starting from the top of the image, find the first pixel that is not transparent which will determine where to place the image on top of the faded grey background (https://legacy.imagemagick.org/discourse-server/viewtopic.php?t=36219)
    $cmdName = if ($script:IM -and $script:IM.Root) { "$($script:IM.Root) convert" } else { "convert" }

    # Show the identify-equivalent command
    # Write-Host ("{0} `"{1}`" -format ""%@"" info:" -f $cmdName, $file)
    $string = & $script:IM.Convert $file -format "%@" info:

    $theArray = $string.Split("+")
    $theAmt = [int]$theArray[2]
    WriteToLogFile "Vertical_Offset              : $theAmt"

    if ($theAmt -lt 500) {
      $theAmt = 500 - $theAmt
      WriteToLogFile "Pushing down                 : $noextension by $theAmt px"

      $outPushed = "$tpps$noextension" + "_pushed.png"
      & $script:IM.Convert $file -background none -gravity north -splice "0x$theAmt" -gravity north -extent 2000x3000 $tpps$noextension"_pushed.png"
	}

    WriteToLogFile "Moving and Copying           : $noextension to: $tpps"
    Move-Item -Path $file -Destination $tpps -Force
    if (Test-Path $tpps$noextension"_pushed.png") {
    }
    else {
      Copy-Item -Path $file -Destination $tpps$noextension"_pushed.png" -Force
    }
  }
}

#################### MAIN ###########################

if (Test-Path $scriptLog) {
  Remove-Item $scriptLog
}

WriteToLogFile "#### START ####"

$Stopwatch = [System.Diagnostics.Stopwatch]::new()
$Stopwatch.Start()

Test-ImageMagick
$test = $global:magick
if ($null -eq $test) {
  WriteToLogFile "Imagemagick                  : Imagemagick is NOT installed. Aborting.... Imagemagick must be installed - https://imagemagick.org/script/download.php"
  exit
}
else {
  WriteToLogFile "Imagemagick                  : Imagemagick is installed. $global:magick"
}
$tmp = $null
$tmp = $PSVersionTable.PSVersion.ToString()
WriteToLogFile "Powershell Version           : $tmp"

# Test-Image variables
$baseImageRatio = [math]::Round(1 / 1.5, 4)
$baseImageW = 399
$baseImageH = 599

# Create dirs
New-Item -ItemType Directory -Force -Path $download_dir | Out-Null
New-Item -ItemType Directory -Force -Path $targetPath_bw | Out-Null
New-Item -ItemType Directory -Force -Path $targetPath_diiivoy | Out-Null
New-Item -ItemType Directory -Force -Path $targetPath_diiivoycolor | Out-Null
New-Item -ItemType Directory -Force -Path $targetPath_rainier | Out-Null
New-Item -ItemType Directory -Force -Path $targetPath_orig | Out-Null
New-Item -ItemType Directory -Force -Path $targetPath_signature | Out-Null
New-Item -ItemType Directory -Force -Path $nobackPathColor | Out-Null
New-Item -ItemType Directory -Force -Path $tmpPeoplePath | Out-Null
New-Item -ItemType Directory -Force -Path $basePath | Out-Null

# restore template files
Convert-TextToBinary -Text $file1 -OutputPath $bps"@zbase-People.jpg"
Convert-TextToBinary -Text $file2 -OutputPath $bps"@zbase-People-Clear2.png"
Convert-TextToBinary -Text $file3 -OutputPath $bps"@zbase-Signature.png"
Convert-TextToBinary -Text $file8 -OutputPath $bps"@zbase-People-Clear3.png"
Ensure-FontAsset -FontPath $fontComfortaa -FontText $file4
Ensure-FontAsset -FontPath $fontFuggles -FontText $file5
Ensure-FontAsset -FontPath $fontMontserrat -FontText $file6
Ensure-FontAsset -FontPath $fontFutura -FontText $file7

#################################
# local font checks
#################################
if (@($fontComfortaa, $fontFuggles, $fontMontserrat, $fontFutura).Where({ -not (Test-Path -LiteralPath $_) }).Count -gt 0) {
  Write-Host "Required local font assets are missing from $basePath. Aborting..." -ForegroundColor Red -BackgroundColor White
  WriteToLogFile "Font check failed: one or more required local font files are missing from $basePath."
  exit 2
}
WriteToLogFile "Font paths                    : $fontComfortaa | $fontFuggles | $fontMontserrat | $fontFutura"

WriteToLogFile "#######################"
WriteToLogFile "# SETTINGS"
WriteToLogFile "#######################"
WriteToLogFile "scriptName                   : $scriptName"
WriteToLogFile "script_path                  : $script_path"
WriteToLogFile "scriptLog                    : $scriptLog"
WriteToLogFile "download_dir                 : $download_dir"
WriteToLogFile "targetPath_bw                : $targetPath_bw"
WriteToLogFile "targetPath_diiivoy           : $targetPath_diiivoy"
WriteToLogFile "targetPath_diiivoycolor      : $targetPath_diiivoycolor"
WriteToLogFile "targetPath_rainier           : $targetPath_rainier"
WriteToLogFile "targetPath_orig              : $targetPath_orig"
WriteToLogFile "targetPath_signature         : $targetPath_signature"
WriteToLogFile "nobackPathColor              : $nobackPathColor"
WriteToLogFile "tmpPeoplePath                : $tmpPeoplePath"
WriteToLogFile "basePath                     : $basePath"

# Init counters
$files_to_process = 0

###################################################
# 3 Process resize and grayscale based on files found in download_dir
###################################################

$filespre = @(Get-ChildItem $dds*.png -Attributes !Directory)

$Counter = 1
$files_to_process = $files_to_process + $filespre.Count
foreach ($filepre in $filespre) {
  $percentComplete = $(($Counter / $filespre.Count) * 100 )
  $Progress = @{
    Activity        = "Working on: '$($filepre)'."
    Status          = "Processing $Counter of $($filespre.Count)"
    PercentComplete = $([math]::Round($percentComplete, 2))
  }
  Write-Progress @Progress -Id 1
  WriteToLogFile "Progress                     : Processing $Counter of $($filespre.Count)"
  # Increment the counter. 
  $Counter++

  $noextension = [System.IO.Path]::GetFileNameWithoutExtension($filepre.FullName)
  WriteToLogFile "Separator                    : ###################################################"
  WriteToLogFile "Working on                   : $filepre"
  WriteToLogFile "Name                         : $noextension"
  $theString = & $script:IM.Identify -format "%w" $filepre
  WriteToLogFile "Geometry                     : $theString"
  if ($theString -ne 2000) {
    WriteToLogFile "Resizing                    : $noextension"
    & $script:IM.Convert $filepre -resize 2000 $filepre
  }
  
  # Before doing anything, copy to another location
  WriteToLogFile "Copying                      : $noextension to $nbpcs"
  Copy-Item -Path $filepre -Destination $nbpcs

  # Validate quality of image
  WriteToLogFile "Test-Image                   : $noextension"
  Test-Image
  Move-Item -Path $filepre -Destination $tpps -Force
}

# Start processing the files to create the posters
$files = @(Get-ChildItem $tpps*.png -Attributes !Directory)
$Counter = 1
$files_to_process = $files.Count

foreach ($file in $files) {
  $percentComplete = $(($Counter / $files.Count) * 100 )
  $Progress = @{
    Activity        = "Working on: '$($file)'."
    Status          = "Processing $Counter of $($files.Count)"
    PercentComplete = $([math]::Round($percentComplete, 2))
  }
  Write-Progress @Progress -Id 1
  WriteToLogFile "Progress                     : Processing $Counter of $($files.Count)"

  # Increment the counter. 
  $Counter++

  $noextension = [System.IO.Path]::GetFileNameWithoutExtension($file.FullName)
  $cleanfilename = $noextension.replace('_ccexpress', '')
  $postertitle = GetBaseFileName $cleanfilename.ToUpper()
  $postertitle_orig = GetBaseFileName $cleanfilename

  Invoke-kometa-bw-style
  Invoke-kometa-signature-style
  Invoke-kometa-diiivoy-style
  Invoke-kometa-diiivoycolor-style
  Invoke-rainier-style

  # Clean up
  $tmpwrite = "$tpps$noextension" + "_pushed.png"
  if (Test-Path $file) {
    WriteToLogFile "Deleting temp file           : $file"
    Remove-Item -Path $file -Force
  }
  if (Test-Path $tmpwrite ) {
    WriteToLogFile "Deleting temp file           : $tmpwrite"
    Remove-Item -Path $tmpwrite -Force
  }
    
}

#######################
# SortFiles
#######################
SortFiles $tppbws # bw
SortFiles $tpds   # diiivoy
SortFiles $tpdcs  # diiivoycolor
SortFiles $tprs   # rainier
SortFiles $tpos   # original
SortFiles $tpss   # signature
SortFiles $nbpcs  # transparent

#######################
# SUMMARY
#######################
WriteToLogFile "#######################"
WriteToLogFile "# SUMMARY"
WriteToLogFile "#######################"

$x = [math]::Round($Stopwatch.Elapsed.TotalMinutes, 2)
$speed = [math]::Round($files_to_process / $Stopwatch.Elapsed.TotalMinutes, 2)
$y = [math]::Round($Stopwatch.Elapsed.TotalMinutes, 2)

$string = "Elapsed time is              : $x minutes"
WriteToLogFile $string

$string = "Files Processed              : $files_to_process in $y minutes"
WriteToLogFile $string

$string = "People Posters per minute    : " + $speed.ToString()
WriteToLogFile $string

$string = "WARNING1 Grayscale Total     : $global:Counter1"
WriteToLogFile $string

$string = "WARNING2 Transparent Total   : $global:Counter2"
WriteToLogFile $string

$string = "WARNING3 Head Chop Total     : $global:Counter3"
WriteToLogFile $string

$string = "WARNING4 Image Ratio Total   : $global:Counter4"
WriteToLogFile $string

$string = "WARNING5 Quality W Total     : $global:Counter5"
WriteToLogFile $string

$string = "WARNING6 Quality H Total     : $global:Counter6"
WriteToLogFile $string

$string = "WARNING7 2000x3000 Total     : $global:Counter7"
WriteToLogFile $string

$tot = $global:Counter1 + $global:Counter2 + $global:Counter3 + $global:Counter4 + $global:Counter5 + $global:Counter6 + $global:Counter7
$tot_chks = $filespre.count * 7
if ($filespre.count -gt 0) {
  $issues_pct = [math]::Round((($tot / $tot_chks) * 100), 2)
}
else {
  $issues_pct = [math]::Round(0, 2)
}
$string = "Total files                  : " + ($filespre.count).ToString()
WriteToLogFile $string 
WriteToLogFile "Total issues                 : $tot"
WriteToLogFile "Total checks                 : $tot_chks"
WriteToLogFile "Percent Issues               : $issues_pct %"

###################################################
# CLEANUP
###################################################
if (Test-Path tmp.txt) {
  Remove-Item -Path tmp.txt -Force | Out-Null
}

WriteToLogFile "#### END ####"
